import re


def _format_value(value):
    if value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    return str(value)


def _parse_path(path_str):
    """Split a trimmed path string into parts, validating by rule 1.

    Returns a list of parts, or None if invalid.
    """
    if not path_str:
        return None
    if path_str.startswith(".") or path_str.endswith("."):
        return None
    segments = path_str.split(".")
    # Consecutive dots or empty segment -> invalid.
    if "" in segments:
        return None
    for seg in segments:
        if not re.fullmatch(r"[A-Za-z0-9_]+", seg):
            return None
    return segments


def _look_up(parts, values):
    """Return (found, value) for a path; found is False if lookup failed."""
    value = None
    for i, part in enumerate(parts):
        if i == 0:
            if isinstance(values, dict) and part in values:
                value = values[part]
            else:
                return False, None
        else:
            if isinstance(value, dict) and part in value:
                value = value[part]
            elif (isinstance(value, (list, tuple)) and part.isdigit()):
                idx = int(part)
                if 0 <= idx < len(value):
                    value = value[idx]
                else:
                    return False, None
            else:
                return False, None
    return True, value


def _process_field(inner, values):
    # inner is the text between the braces, not including them.
    # Empty field {}.
    if inner == "":
        raise ValueError("empty field")
    # Determine if there is a default: the first '|' separates path from default.
    if "|" in inner:
        path_part, default_text = inner.split("|", 1)
    else:
        path_part, default_text = inner, None
    # Whitespace around the path is ignored; default text is exact.
    path_str = path_part.strip()
    parts = _parse_path(path_str)
    if parts is None:
        raise ValueError("invalid path: %r" % path_str)
    found, value = _look_up(parts, values)
    if not found:
        if default_text is not None:
            return default_text
        raise KeyError(path_str)
    return _format_value(value)


def render(template, values):
    """The template with its fields filled from `values`. See TASK.md."""
    out = []
    i = 0
    n = len(template)
    while i < n:
        ch = template[i]
        if ch == "{":
            # Escaped?
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            # Field start. Find the closing brace; '{' inside field is invalid.
            j = i + 1
            found_close = -1
            while j < n:
                c = template[j]
                if c == "}":
                    found_close = j
                    break
                if c == "{":
                    raise ValueError("a '{' inside a field is invalid")
                j += 1
            if found_close == -1:
                raise ValueError("a '{' with no closing '}'")
            inner = template[i + 1:found_close]
            out.append(_process_field(inner, values))
            i = found_close + 1
            continue
        elif ch == "}":
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
                continue
            raise ValueError("a '}' with no opening '{'")
        else:
            out.append(ch)
            i += 1
    return "".join(out)
